const EQUIPMENT_ICON_MAP=new Map(EQUIPMENT_ICONS.map(g=>[g.id,g]));
function equipmentIcon(k,size=48){
 const g=EQUIPMENT_ICON_MAP.get(k);if(!g)return '';
 const n=Number.isFinite(Number(size))?Math.max(1,Math.min(512,Number(size))):48;
 return '<img class="equipment-icon" data-equipment="'+g.id+'" src="'+(n>64?g.image:g.thumbnail)+'" width="'+n+'" height="'+n+'" alt="" aria-hidden="true" decoding="async" loading="lazy">';
}
